/// Find a suite by the name the command line was given.
#[must_use]
pub fn find(name: &str) -> Option<&'static Suite> {
    SUITES.iter().find(|s| s.name == name)
}

/// The `ORDER BY` a tuned ClickHouse table gets, which is the whole reason the tuned row exists.
///
/// A MergeTree sorting key is not a hint. It decides the physical order of the parts and it decides
/// which granules a `WHERE` can skip without reading them, and a ClickHouse measured without one is
/// not the ClickHouse anybody deploys. So the tuned server row gets the key and the `clickhouse
/// local` row does not, and they are two rows rather than one because they are two systems.
///
/// The ClickBench key is not ours. It is the one in the official `create.sql` in the ClickBench
/// repository, copied exactly, because a ClickBench number measured against a key we picked is a
/// number about our tuning rather than about ClickHouse. The `smoke` key is ours, since `smoke` is
/// not a benchmark and has no official anything, and it is chosen the way the ClickBench one is
/// chosen: the column a query puts a range predicate on goes first, so that `k < 100` reads the
/// granules that can contain it and skips the rest.
///
/// Everything else gets `tuple()`, which is no sorting key at all. That is a refusal rather than a
/// default. Inventing a key for a suite nobody has settled the shape of would put a number in a
/// table whose tuning nobody had reviewed.
#[must_use]
pub fn sorting_key(suite: &str, table: &str) -> &'static str {
    match (suite, table) {
        ("clickbench", "hits") => "(CounterID, EventDate, UserID, EventTime, WatchID)",
        ("smoke", "smoke") => "(k, tag)",
        _ => "tuple()",
    }
}

/// The queries of a suite, where this harness has them.
#[must_use]
pub fn queries(name: &str) -> Option<&'static [Query]> {
    match name {
        "smoke" => Some(SMOKE),
        "clickbench" => Some(CLICKBENCH),
        "tpch" => Some(TPCH),
        _ => None,
    }
}

#[cfg(test)]
mod tests {
    use super::{CLICKBENCH, SMOKE, SUITES, TPCH, find, queries, sorting_key};

    #[test]
    fn a_suite_this_harness_has_the_queries_of_says_how_many_it_has() {
        for suite in SUITES {
            if let Some(got) = queries(suite.name) {
                assert_eq!(got.len(), suite.queries, "{} miscounts itself", suite.name);
            }
        }
    }

    #[test]
    fn the_clickbench_text_is_the_official_text_and_not_a_translation() {
        // Three spot checks against the official files rather than a checksum, because a checksum
        // says a byte moved and these say which byte and why it matters.
        let q1 = CLICKBENCH.iter().find(|q| q.name == "q1").unwrap();
        assert_eq!(q1.sql, "SELECT COUNT(*) FROM hits");
        // ClickHouse writes the length in bytes and DuckDB writes it in characters, and this is
        // the whole reason per engine text exists.
        let q28 = CLICKBENCH.iter().find(|q| q.name == "q28").unwrap();
        assert!(q28.sql_for("clickhouse-local").unwrap().contains("AVG(length(URL))"));
        assert!(q28.sql_for("duckdb").unwrap().contains("AVG(STRLEN(URL))"));
        // DataFusion quotes every identifier because it lowercases the ones nobody quoted.
        let q2 = CLICKBENCH.iter().find(|q| q.name == "q2").unwrap();
        assert!(q2.sql_for("datafusion").unwrap().contains("\"AdvEngineID\""), "{q2:?}");
    }

    #[test]
    fn an_engine_nobody_wrote_a_dialect_for_gets_the_default_text() {
        for query in CLICKBENCH {
            assert_eq!(query.sql_for("clickhouse-server"), Some(query.sql), "{}", query.name);
            assert_eq!(query.sql_for("clickhouse-local"), Some(query.sql), "{}", query.name);
        }
    }

    #[test]
    fn polars_is_short_exactly_the_four_its_sql_context_has_no_function_for() {
        let short: Vec<&str> =
            CLICKBENCH.iter().filter(|q| q.sql_for("polars").is_none()).map(|q| q.name).collect();
        assert_eq!(short, vec!["q28", "q29", "q36", "q43"]);
    }

    #[test]
    fn every_query_a_dialect_takes_away_says_why_in_a_sentence() {
        for query in CLICKBENCH.iter().chain(SMOKE) {
            for (engine, why) in query.absent() {
                assert!(why.len() > 20, "{} says nothing about {engine}", query.name);
            }
            for dialect in query.dialects {
                assert!(!dialect.why.is_empty(), "{} has a dialect with no reason", query.name);
                assert!(!dialect.engines.is_empty(), "{} has a dialect for nobody", query.name);
            }
        }
    }

    #[test]
    fn a_query_the_default_text_covers_is_not_reported_as_absent() {
        let q1 = CLICKBENCH.iter().find(|q| q.name == "q1").unwrap();
        assert!(q1.absent().is_empty());
        assert!(q1.absent_for("polars").is_none());
        let q43 = CLICKBENCH.iter().find(|q| q.name == "q43").unwrap();
        assert!(q43.absent_for("polars").unwrap().contains("date_trunc"));
        assert!(q43.absent_for("duckdb").is_none());
    }

    #[test]
    fn tpch_is_one_query_set_and_only_polars_is_short_of_it() {
        // Every engine was asked against a real SF 0.01 corpus before this was written. DuckDB,
        // ClickHouse and DataFusion took all twenty two unmodified, which is why there is no
        // dialect for any of them, and a diff that adds one has to say what changed.
        for query in TPCH {
            for engine in ["duckdb", "clickhouse-local", "clickhouse-server", "datafusion"] {
                assert_eq!(query.sql_for(engine), Some(query.sql), "{} for {engine}", query.name);
            }
        }
        let short: Vec<&str> =
            TPCH.iter().filter(|q| q.sql_for("polars").is_none()).map(|q| q.name).collect();
        assert_eq!(short, vec!["q02", "q13", "q17"]);
    }

    #[test]
    fn the_tpch_text_is_one_line_with_no_indentation_left_in_it() {
        // The upstream files are indented over twenty lines each. What an engine gets is one line,
        // because a query with a newline in it is a query some CLI drivers split and others do not.
        for query in TPCH {
            assert!(!query.sql.contains('\n'), "{} has a newline", query.name);
            assert!(!query.sql.contains("  "), "{} has leftover indentation", query.name);
        }
    }

    #[test]
    fn every_clickbench_query_reads_the_one_table_the_suite_declares() {
        for query in CLICKBENCH {
            for engine in ["clickhouse-local", "duckdb", "datafusion"] {
                let sql = query.sql_for(engine).expect("has text");
                assert!(sql.contains(" hits"), "{} for {engine} reads no hits", query.name);
            }
        }
    }

    #[test]
    fn the_smoke_suite_counts_its_own_queries() {
        assert_eq!(find("smoke").unwrap().queries, SMOKE.len());
    }

    #[test]
    fn the_smoke_suite_is_not_comparable_to_anything() {
        // The flag is what a report reads to decide whether it may name a board. A smoke number
        // that claimed comparability would be the exact failure section 15.1 is written to prevent.
        assert!(!find("smoke").unwrap().comparable);
    }

    #[test]
    fn every_suite_says_what_it_needs_and_what_it_is_not_for() {
        for suite in SUITES {
            assert!(!suite.needs.is_empty(), "{} does not say what it needs", suite.name);
            assert!(suite.note.len() > 120, "{} needs a real note", suite.name);
        }
    }

    #[test]
    fn a_suite_that_has_queries_says_what_they_read() {
        for suite in SUITES {
            if queries(suite.name).is_some() {
                assert!(!suite.tables.is_empty(), "{} has queries and no tables", suite.name);
            }
        }
    }

    #[test]
    fn the_queries_only_name_tables_the_suite_declared() {
        // A query naming a table nobody loads is an error at run time in four different engines
        // with four different messages, and this is the cheap place to catch it.
        let smoke = find("smoke").unwrap();
        for query in SMOKE {
            for table in smoke.tables {
                assert!(query.sql.contains(table), "{} does not read {table}", query.name);
            }
        }
    }

    #[test]
    fn nothing_in_the_smoke_queries_is_written_in_one_dialect_only() {
        for query in SMOKE {
            assert!(!query.sql.contains("::"), "{} casts the DuckDB way", query.name);
            assert!(!query.sql.contains("ORDER BY 2"), "{} orders positionally", query.name);
        }
    }

    #[test]
    fn a_name_nobody_defined_is_none_rather_than_a_default() {
        assert!(find("clickbench-but-only-the-fast-ones").is_none());
    }

    #[test]
    fn a_suite_nobody_has_settled_gets_no_sorting_key_rather_than_an_invented_one() {
        assert_eq!(sorting_key("tpch", "lineitem"), "tuple()");
        assert_eq!(sorting_key("h2o", "x"), "tuple()");
        // Including the right suite and the wrong table, which is the shape a typo takes.
        assert_eq!(sorting_key("clickbench", "hit"), "tuple()");
    }

    #[test]
    fn the_clickbench_key_is_the_one_out_of_the_official_create_sql() {
        // Copied from the ClickBench repository rather than chosen. Changing this changes what a
        // ClickBench number means, so it should be a diff somebody has to justify.
        assert_eq!(
            sorting_key("clickbench", "hits"),
            "(CounterID, EventDate, UserID, EventTime, WatchID)"
        );
    }

    #[test]
    fn the_smoke_key_leads_with_the_column_a_query_puts_a_range_on() {
        // q2 is `WHERE k < 100`, which is the only predicate in the suite a sorting key can help,
        // so a key that did not start with k would be a key that does nothing and a tuned row that
        // was not tuned.
        let key = sorting_key("smoke", "smoke");
        assert!(key.starts_with("(k"), "{key}");
        let filtering = SMOKE.iter().find(|q| q.name == "q2").unwrap();
        assert!(filtering.sql.contains("k <"), "{}", filtering.sql);
    }

    #[test]
    fn the_smoke_queries_between_them_touch_the_shapes_that_matter() {
        let shapes: Vec<&str> = SMOKE.iter().map(|q| q.shape).collect();
        assert!(shapes.iter().any(|s| s.contains("group by")));
        assert!(shapes.iter().any(|s| s.contains("join")));
        assert!(shapes.iter().any(|s| s.contains("top k")));
    }
}
